    /** Share a claim with another person; answers with the claim's own person and each holder of a share. */
    @PostMapping("/claims/{claimId}/share")
    public List<PersonView> share(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId, @RequestHeader("X-User") @NotBlank String user,
            @Valid @RequestBody ShareForm form) {
        String sheet = sheetId.trim();
        List<Long> moved = claims.share(sheet, user.trim(), claimId, form.personId(),
                new BigDecimal(form.share().trim()));
        return moved.stream().map(id -> view(sheet, id)).toList();
    }

    /** Defer an OPEN claim until a date after the sheet's today. */
    @PostMapping("/claims/{claimId}/defer")
    public PersonView defer(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId, @RequestHeader("X-User") @NotBlank String user,
            @Valid @RequestBody DeferForm form) {
        String sheet = sheetId.trim();
        return view(sheet, claims.defer(sheet, user.trim(), claimId, form.until()));
    }

    /** A steward re-dates an OPEN or PENDING claim. */
    @PostMapping("/claims/{claimId}/redate")
    public PersonView redate(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId, @RequestHeader("X-User") @NotBlank String user,
        log(sheetId, user, claim, owner);
        claims.flush();
        events.publishEvent(new ClaimChanged(event, sheetId, user, owner == null ? "" : owner.getName(),
                claim.getAmount(), claim.getDate(), null, null));
        rollup.changed(sheetId, user, before);
        return claim.getPersonId();
    }

    /**
     * Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it the claim
     * counts in no total, is not overdue, cannot be settled and no statement binds it (see
     * {@link Dues#deferred}). A claim not OPEN, a date not after today, or a claim due by a date inside a closed
     * period is refused and nothing changes. Returns the person it belongs to.
     */
